from collections.abc import Iterable
from dataclasses import dataclass


@dataclass(frozen=True)
class Event:
    seq: int
    kind: str
    movement: str
    depot: str | None = None


def export(events: Iterable[Event], *, depot: str | None = None) -> list[Event]:
    """Deliver events in sequence order, optionally limiting shipments to one depot."""
    ordered = sorted(events, key=lambda event: event.seq)
    # A void may cancel a shipment delivered in an earlier batch.
    return [
        event
        for event in ordered
        if event.kind != "note"
        and (depot is None or event.kind != "ship" or event.depot == depot)
    ]


def active_movements(depot: str, delivered: Iterable[Event]) -> set[str]:
    active = set()
    for event in delivered:
        if event.kind == "ship" and event.depot == depot:
            active.add(event.movement)
        elif event.kind == "void":
            active.discard(event.movement)
    return active

