@dataclass(frozen=True)
class Event:
    seq: int
    kind: str
    movement: str
    depot: str | None = None


def export(events: Iterable[Event], *, depot: str | None = None) -> list[Event]:
    """Deliver events in sequence order, optionally limiting shipments to one depot."""
    ordered = sorted(events, key=lambda event: event.seq)
    return _deliver(ordered, depot=depot)


def page(
    events: Iterable[Event], *, after: int, limit: int, depot: str | None = None
) -> tuple[list[Event], int]:
    """Deliver a batch and return the last source sequence scanned."""
    ordered = sorted(
        (event for event in events if event.seq > after), key=lambda event: event.seq
    )
    batch = ordered[:limit]
    checkpoint = batch[-1].seq if batch else after
    return _deliver(batch, depot=depot), checkpoint


def _deliver(ordered: Iterable[Event], *, depot: str | None) -> list[Event]:
    # A void may cancel a shipment delivered in an earlier batch.
    return [
        event
        for event in ordered
        if event.kind != "note"
        and (depot is None or event.kind != "ship" or event.depot == depot)
