from dataclasses import dataclass
from heapq import nsmallest


@dataclass(frozen=True)
class Event:
    seq: int
    kind: str
    movement: str
    depot: str | None = None


def _filter_delivery(events: Iterable[Event], depot: str | None) -> list[Event]:
    # Unscoped voids may revoke shipments from earlier batches.
    return [
        event
        for event in events
        if event.kind != "note"
        and (depot is None or event.kind != "ship" or event.depot == depot)
    ]


def export(events: Iterable[Event], *, depot: str | None = None) -> list[Event]:
    ordered = sorted(events, key=lambda event: event.seq)
    return _filter_delivery(ordered, depot)


def page(
    events: Iterable[Event], *, after: int, limit: int, depot: str | None = None
) -> tuple[list[Event], int]:
    """Deliver a page and return the checkpoint of its last scanned source event."""
    eligible = (event for event in events if event.seq > after)
    scanned = nsmallest(limit, eligible, key=lambda event: event.seq)
    checkpoint = scanned[-1].seq if scanned else after
    return _filter_delivery(scanned, depot), checkpoint


def active_movements(depot: str, delivered: Iterable[Event]) -> set[str]:
    active = set()
    for event in delivered:
        if event.kind == "ship" and event.depot == depot:
